    (NEWID(), @HomeId, N'ImageGallery', 4,
     N'{"layout":"grid","columns":3,"images":[{"imageUrl":"/uploads/roastino-gallery-bar.jpg","altText":"بارِ قهوه‌ی رستینو"},{"imageUrl":"/uploads/roastino-gallery-beans.jpg","altText":"قفسه‌ی دانه‌های قهوه"},{"imageUrl":"/uploads/roastino-gallery-space.jpg","altText":"فضای کافه"}]}',
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"2rem","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @HomeId, N'CardGrid', 5,
     REPLACE(REPLACE(REPLACE(N'{"sectionTitle":"سری به ما بزنید","columns":3,"layout":"stacked","cards":[{"icon":"map-pin","title":"نشانی","description":"{{ADDRESS}}","linkText":"مسیریابی","linkUrl":"/fa/contact"},{"icon":"clock","title":"ساعتِ کار","description":"{{HOURS}}"},{"icon":"phone","title":"تماس","description":"{{PHONE}}","linkText":"صفحه‌ی تماس با ما","linkUrl":"/fa/contact"}]}', N'{{ADDRESS}}', @AddressJson), N'{{HOURS}}', @HoursJson), N'{{PHONE}}', @PhoneJson),
     N'{"backgroundColor":"#F3E6D3","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @HomeId, N'Newsletter', 6,
     N'{"style":"brand","title":"قهوه‌ی تازه که رسید، خبرتان می‌کنیم","description":"ماهی یکی‌دو ایمیل؛ فقط دانه‌های تازه و خبرهای کافه.","buttonText":"عضویت","placeholder":"ایمیلِ شما"}',
     N'{"backgroundColor":"transparent","paddingTop":"2rem","paddingBottom":"2rem","paddingLeft":"0","paddingRight":"0"}');

