-- تماس با ما  (/fa/contact)
INSERT INTO Pages (Id, Title, Slug, Status, MetaTitle, MetaDescription, Culture, LocalizationGroupId, CreatedAt, UpdatedAt, PublishedAt)
VALUES (@ContactId, N'تماس با ما', N'contact', 'Published', N'تماس با ما | رستینو', N'نشانی، ساعتِ کار و راه‌های تماس با رستینو.', 'fa', NULL, SYSUTCDATETIME(), SYSUTCDATETIME(), SYSUTCDATETIME());
INSERT INTO PageBlocks (Id, PageId, BlockType, SortOrder, Data, Styles) VALUES
    (NEWID(), @ContactId, N'Heading', 0,
     N'{"text":"تماس با ما","subtitle":"سؤالی درباره‌ی قهوه دارید یا می‌خواهید دانه‌ای را برایتان کنار بگذاریم؟ پیام بدهید، یا بهتر از آن، سری به کافه بزنید.","level":"h1","alignment":"center"}',
     N'{"backgroundColor":"#F3E6D3","paddingTop":"2rem","paddingBottom":"2rem","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @ContactId, N'Columns', 1,
     REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(N'{"columnCount":2,"gap":"2rem","columns":[{"width":"38%","blocks":[{"blockType":"CardGrid","data":"{\"columns\":1,\"layout\":\"inline\",\"cards\":[{\"icon\":\"map-pin\",\"title\":\"نشانی\",\"description\":\"{{N_ADDRESS}}\"},{\"icon\":\"clock\",\"title\":\"ساعتِ کار\",\"description\":\"{{N_HOURS}}\"},{\"icon\":\"phone\",\"title\":\"تلفن\",\"description\":\"{{N_PHONE}}\"},{\"icon\":\"brand-instagram\",\"title\":\"اینستاگرام\",\"description\":\"{{N_INSTAGRAM}}\"}]}"}]},{"width":"60%","blocks":[{"blockType":"ContactForm","data":"{\"title\":\"پیام بفرستید\",\"description\":\"پیامتان را بنویسید؛ به‌زودی پاسخ می‌دهیم.\",\"recipientEmail\":\"{{N_RECIPIENT_EMAIL}}\",\"submitButtonText\":\"ارسالِ پیام\",\"fields\":[{\"label\":\"نام\",\"name\":\"name\",\"type\":\"text\",\"required\":true,\"placeholder\":\"نامِ شما\"},{\"label\":\"ایمیل\",\"name\":\"email\",\"type\":\"email\",\"required\":true,\"placeholder\":\"email@example.com\"},{\"label\":\"موضوع\",\"name\":\"subject\",\"type\":\"text\",\"required\":false,\"placeholder\":\"مثلاً خریدِ دانه‌ی قهوه\"},{\"label\":\"پیام\",\"name\":\"message\",\"type\":\"textarea\",\"required\":true,\"placeholder\":\"پیامتان را بنویسید\"}]}"}]}]}', N'{{N_ADDRESS}}', @AddressJson2), N'{{N_HOURS}}', @HoursJson2), N'{{N_PHONE}}', @PhoneJson2), N'{{N_INSTAGRAM}}', @InstagramJson2), N'{{N_RECIPIENT_EMAIL}}', @RecipientEmailJson2),
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @ContactId, N'MapEmbed', 2,
     REPLACE(N'{"embedUrl":"{{MAP_EMBED_URL}}","height":420}', N'{{MAP_EMBED_URL}}', @MapEmbedUrlJson),
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"3rem","paddingLeft":"0","paddingRight":"0"}');

COMMIT TRANSACTION;

SELECT p.Slug, p.Title, p.Status, COUNT(b.Id) AS Blocks
FROM Pages p LEFT JOIN PageBlocks b ON b.PageId = p.Id
WHERE p.Culture = 'fa' AND p.Slug IN (N'', N'menu', N'contact')
GROUP BY p.Slug, p.Title, p.Status;
